('a1e19b6c-03ba-5dbb-9110-b7cf4143bcd5', 'two-sum', 'Pair With Target Sum', 'Return the indices [i, j] (i < j) of the first pair of numbers in `nums` that add up to `target`, scanning j from left to right. Return [] if there is none.', 'twoSum', '{"javascript":"function twoSum(nums, target) {\n  // your code\n}\n"}', '[{"input":[[2,7,11,15],9],"description":"example","expected":[0,1]}]', '[{"input":[[3,2,4],6],"description":"pair not at the start","expected":[1,2]},{"input":[[],5],"description":"empty array","expected":[]},{"input":[[3,3],6],"description":"duplicate values","expected":[0,1]},{"input":[[1,2,3],100],"description":"no pair exists","expected":[]},{"input":[[-1,-2,-3,-4],-6],"description":"negative numbers","expected":[1,3]}]', 'javascript', 'function twoSum(nums, target) { const seen = new Map(); for (let j = 0; j < nums.length; j++) { const need = target - nums[j]; if (seen.has(need)) return [seen.get(need), j]; if (!seen.has(nums[j])) seen.set(nums[j], j); } return []; }', NULL, 10, 'arrays,hashing', 'problem-solving,data-structures,javascript', 1),
('60b27784-a524-5eb4-9753-d33f78659dbc', 'balanced-brackets', 'Balanced Brackets', 'Return true if every bracket in `s` — (), [] and {} — is closed in the right order. Other characters are ignored.', 'isBalanced', '{"javascript":"function isBalanced(s) {\n  // your code\n}\n"}', '[{"input":["([]){}"],"description":"example","expected":true}]', '[{"input":[""],"description":"empty string","expected":true},{"input":["(]"],"description":"wrong closing type","expected":false},{"input":["(("],"description":"unclosed bracket","expected":false},{"input":["a(b[c]d)e"],"description":"other characters ignored","expected":true},{"input":["())("],"description":"close before open","expected":false}]', 'javascript', 'function isBalanced(s) { const st = []; const pair = { '')'': ''('', '']'': ''['', ''}'': ''{'' }; for (const c of s) { if (''([{''.includes(c)) st.push(c); else if (c in pair) { if (st.pop() !== pair[c]) return false; } } return st.length === 0; }', NULL, 10, 'stacks,strings', 'problem-solving,data-structures,javascript', 2),
('65777708-877b-526e-a643-c4914957ae11', 'second-largest', 'Second Largest Distinct', 'Return the second largest distinct value in `nums`, or null if it does not exist.', 'secondLargest', '{"javascript":"function secondLargest(nums) {\n  // your code\n}\n"}', '[{"input":[[4,9,2,7]],"description":"example","expected":7}]', '[{"input":[[5,5,5]],"description":"all equal","expected":null},{"input":[[1]],"description":"single element","expected":null},{"input":[[9,9,8]],"description":"duplicate maximum","expected":8},{"input":[[-3,-1,-2]],"description":"negative numbers","expected":-2}]', 'javascript', 'function secondLargest(nums) { const s = [...new Set(nums)].sort((a, b) => b - a); return s.length > 1 ? s[1] : null; }', NULL, 10, 'arrays', 'problem-solving,javascript', 1),
('0304808e-8dfd-52db-ae8e-6c9350115858', 'merge-intervals', 'Merge Booking Intervals', 'Given [start, end] intervals in any order, merge all overlapping or touching intervals and return them sorted by start.', 'mergeIntervals', '{"javascript":"function mergeIntervals(intervals) {\n  // your code\n}\n"}', '[{"input":[[[1,3],[2,6],[8,10]]],"description":"example","expected":[[1,6],[8,10]]}]', '[{"input":[[]],"description":"no intervals","expected":[]},{"input":[[[5,7],[1,2]]],"description":"unsorted input","expected":[[1,2],[5,7]]},{"input":[[[1,4],[4,5]]],"description":"touching intervals","expected":[[1,5]]},{"input":[[[1,10],[2,3],[4,5]]],"description":"nested intervals","expected":[[1,10]]}]', 'javascript', 'function mergeIntervals(iv) { const s = iv.map(x => [...x]).sort((a, b) => a[0] - b[0]); const out = []; for (const x of s) { const last = out[out.length - 1]; if (last && x[0] <= last[1]) last[1] = Math.max(last[1], x[1]); else out.push(x); } return out; }', NULL, 10, 'sorting,arrays', 'problem-solving,algorithms,javascript', 2),
('d20c0f81-bf9f-57de-8c3e-fa050172ed0f', 'dept-headcount', 'Headcount per Department', 'Return every department name with its number of employees as `headcount`, including departments with no employees. Order by headcount descending, then name.', 'query', '{"sql":"-- employees(id, name, dept_id, salary), departments(id, name)\nSELECT ..."}', '[{"setup":"INSERT INTO departments VALUES (1,''Engineering''),(2,''Sales''),(3,''Support'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Ravi'',1,72000),(3,''Meera'',2,55000),(4,''Kiran'',2,48000),(5,''Imran'',3,40000);","description":"example data"}]', '[{"setup":"INSERT INTO departments VALUES (1,''Engineering''),(2,''Sales''),(3,''Legal'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Ravi'',2,60000);","description":"department with no employees"},{"setup":"INSERT INTO departments VALUES (1,''Engineering'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Tanvi'',NULL,50000),(3,''Omkar'',1,65000);","description":"employee without a department"},{"setup":"INSERT INTO departments VALUES (1,''Engineering''),(2,''Sales'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Ravi'',1,90000),(3,''Meera'',2,70000),(4,''Kiran'',2,70000),(5,''Yash'',2,30000);","description":"tied headcounts ordered by name"}]', 'sql', 'SELECT d.name, COUNT(e.id)::int AS headcount FROM departments d LEFT JOIN employees e ON e.dept_id = d.id GROUP BY d.name ORDER BY headcount DESC, d.name', 'CREATE TABLE departments (id INT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE employees (id INT PRIMARY KEY, name TEXT NOT NULL, dept_id INT REFERENCES departments(id), salary INT NOT NULL);', 10, 'sql,joins,aggregation', 'sql,dbms', 2),
('05a9eefa-9082-572a-a4dd-15955961429f', 'second-highest-salary', 'Second Highest Salary', 'Return one row with column `second_highest`: the second highest distinct salary, or NULL if there is none.', 'query', '{"sql":"SELECT ... AS second_highest"}', '[{"setup":"INSERT INTO departments VALUES (1,''Engineering''),(2,''Sales''),(3,''Support'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Ravi'',1,72000),(3,''Meera'',2,55000),(4,''Kiran'',2,48000),(5,''Imran'',3,40000);","description":"example data"}]', '[{"setup":"INSERT INTO departments VALUES (1,''Engineering''),(2,''Sales'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Ravi'',1,90000),(3,''Meera'',2,70000),(4,''Kiran'',2,70000),(5,''Yash'',2,30000);","description":"tied top salaries"},{"setup":"INSERT INTO departments VALUES (1,''Engineering'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000);","description":"only one employee"},{"setup":"INSERT INTO departments VALUES (1,''Engineering'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Tanvi'',NULL,50000),(3,''Omkar'',1,65000);","description":"mixed departments"}]', 'sql', 'SELECT (SELECT DISTINCT salary FROM employees ORDER BY salary DESC OFFSET 1 LIMIT 1) AS second_highest', 'CREATE TABLE departments (id INT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE employees (id INT PRIMARY KEY, name TEXT NOT NULL, dept_id INT REFERENCES departments(id), salary INT NOT NULL);', 10, 'sql,subqueries', 'sql', 2),
('e0d1a8b6-0b8c-52c0-b406-ff58c73d5bc7', 'employee-departments', 'Employees and Their Departments', 'Return `name` and `department` for every employee, with department NULL when they have none. Order by name.', 'query', '{"sql":"SELECT ..."}', '[{"setup":"INSERT INTO departments VALUES (1,''Engineering''),(2,''Sales''),(3,''Support'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Ravi'',1,72000),(3,''Meera'',2,55000),(4,''Kiran'',2,48000),(5,''Imran'',3,40000);","description":"example data"}]', '[{"setup":"INSERT INTO departments VALUES (1,''Engineering'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Tanvi'',NULL,50000),(3,''Omkar'',1,65000);","description":"employee without a department"},{"setup":"INSERT INTO departments VALUES (1,''Engineering'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000);","description":"single employee"}]', 'sql', 'SELECT e.name, d.name AS department FROM employees e LEFT JOIN departments d ON d.id = e.dept_id ORDER BY e.name', 'CREATE TABLE departments (id INT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE employees (id INT PRIMARY KEY, name TEXT NOT NULL, dept_id INT REFERENCES departments(id), salary INT NOT NULL);', 10, 'sql,joins', 'sql', 1),
('bee39a3b-aa1f-5a28-8717-3f1de09f6f07', 'high-paying-departments', 'High-Paying Departments', 'Return `name` and `avg_salary` (rounded to a whole number) for departments whose average salary is above 50000. Order by avg_salary descending.', 'query', '{"sql":"SELECT ..."}', '[{"setup":"INSERT INTO departments VALUES (1,''Engineering''),(2,''Sales''),(3,''Support'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Ravi'',1,72000),(3,''Meera'',2,55000),(4,''Kiran'',2,48000),(5,''Imran'',3,40000);","description":"example data"}]', '[{"setup":"INSERT INTO departments VALUES (1,''Engineering''),(2,''Sales'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Ravi'',1,90000),(3,''Meera'',2,70000),(4,''Kiran'',2,70000),(5,''Yash'',2,30000);","description":"average exactly above and below the line"},{"setup":"INSERT INTO departments VALUES (1,''Engineering''),(2,''Sales''),(3,''Legal'');\nINSERT INTO employees VALUES (1,''Asha'',1,90000),(2,''Ravi'',2,60000);","description":"department with no employees"}]', 'sql', 'SELECT d.name, ROUND(AVG(e.salary))::int AS avg_salary FROM departments d JOIN employees e ON e.dept_id = d.id GROUP BY d.name HAVING AVG(e.salary) > 50000 ORDER BY avg_salary DESC', 'CREATE TABLE departments (id INT PRIMARY KEY, name TEXT NOT NULL);
