('e8a49e28-39aa-57c1-a1c3-2aa77784346c', NULL, 'quantitative', 'time-work', 2, 'A can finish a job in 12 days and B in 24 days. Working together, how many days will they take?', '["10","8","18","7"]', 1, 'Combined rate = 1/12 + 1/24, so time = 12×24/(12+24) = 8 days.'),
('0b232229-4471-566c-9234-96917782241d', NULL, 'quantitative', 'time-work', 2, 'A can finish a job in 10 days and B in 15 days. Working together, how many days will they take?', '["8","12.5","6","5"]', 2, 'Combined rate = 1/10 + 1/15, so time = 10×15/(10+15) = 6 days.'),
('dcba92d9-3284-55cb-80a9-c2e3788df2ef', NULL, 'quantitative', 'time-work', 2, 'A can finish a job in 20 days and B in 30 days. Working together, how many days will they take?', '["14","25","11","12"]', 3, 'Combined rate = 1/20 + 1/30, so time = 20×30/(20+30) = 12 days.'),
('c919baf8-f835-51fb-a0a8-a8db2026ba8a', NULL, 'quantitative', 'time-work', 2, 'A can finish a job in 6 days and B in 12 days. Working together, how many days will they take?', '["4","6","9","3"]', 0, 'Combined rate = 1/6 + 1/12, so time = 6×12/(6+12) = 4 days.'),
