('5e0ced26-2f20-542c-8431-619e29d3ea83', NULL, 'verbal', 'sentence-correction', 2, 'Which sentence is grammatically correct?', '["Each of the students have a laptop.","Each of the students has a laptop.","Each of the student has a laptop.","Each of the students having a laptop."]', 1, '"Each" is singular, so "has".'),
('9ffd2d68-bc24-5329-a116-a0774f79dc3b', NULL, 'verbal', 'sentence-correction', 2, 'Which sentence is grammatically correct?', '["He is senior than me.","He is senior to me.","He is more senior than to me.","He is senior from me."]', 1, '"Senior" takes "to".'),
('1799f66b-47a6-58d1-9425-e81b15a5ab7e', NULL, 'verbal', 'sentence-correction', 2, 'Which sentence is grammatically correct?', '["I have been working here since five years.","I am working here for five years.","I have been working here for five years.","I working here since five years."]', 2, 'A duration takes "for" with the present perfect continuous.'),
('2f7447ce-7a68-53df-8f13-916a7399e6d7', NULL, 'verbal', 'sentence-correction', 2, 'Which sentence is grammatically correct?', '["Neither the manager nor the clerks was present.","Neither the manager nor the clerks were present.","Neither the manager or the clerks were present.","Neither the manager nor the clerks is present."]', 1, 'With "neither…nor", the verb agrees with the nearer subject ("clerks").'),
('328a86f9-ee51-5146-a9af-b1e6add21822', NULL, 'verbal', 'sentence-correction', 2, 'Which sentence is grammatically correct?', '["The news are good.","The news is good.","The news were good.","The newses are good."]', 1, '"News" is uncountable and singular.'),
('55f9159c-f353-581a-a8f6-ab71335b6e20', NULL, 'verbal', 'prepositions', 1, 'Fill in the blank: She is good ___ mathematics.', '["at","in","on","for"]', 0, 'Correct usage: "She is good at mathematics."'),
('28ce65e5-d8ee-513a-bfdf-4f2560645966', NULL, 'verbal', 'prepositions', 1, 'Fill in the blank: He insisted ___ paying the bill.', '["at","on","for","in"]', 1, 'Correct usage: "He insisted on paying the bill."'),
('fdbffcc2-f254-544e-aacd-5c95a4695c9e', NULL, 'verbal', 'prepositions', 1, 'Fill in the blank: We arrived ___ the airport early.', '["to","in","at","on"]', 2, 'Correct usage: "We arrived at the airport early."'),
('7b5b185e-d13a-5a2f-bd65-42c661b087a5', NULL, 'verbal', 'prepositions', 1, 'Fill in the blank: She is fond ___ music.', '["with","for","about","of"]', 3, 'Correct usage: "She is fond of music."'),
('9a3e1580-9b1f-5a7b-8dff-d6bec29de100', NULL, 'verbal', 'prepositions', 1, 'Fill in the blank: He was accused ___ theft.', '["of","for","with","about"]', 0, 'Correct usage: "He was accused of theft."'),
('f753ebba-9d5f-58ca-bd79-350ae797ba42', NULL, 'verbal', 'prepositions', 1, 'Fill in the blank: The train is ___ time today.', '["in","on","at","by"]', 1, 'Correct usage: "The train is on time today."')
